-- Initial schema: domains, sources, records and golden records.
--
-- Not applied yet. The local engine keeps its data in JSON files under
-- <project>/.fita/ until the PostgreSQL store exists. Internal ids are UUID v7
-- generated by the application.

create extension if not exists btree_gist;

create schema if not exists fita;

create table fita.domain (
  id          uuid primary key,
  name        text not null unique,
  prefix      text not null unique check (prefix ~ '^[a-z0-9]+$'),
  created_at  timestamptz not null default now()
);

create table fita.source (
  id          uuid primary key,
  domain_id   uuid not null references fita.domain,
  name        text not null unique,
  created_at  timestamptz not null default now()
);

create table fita.source_record (
  id           uuid primary key,
  source_id    uuid not null references fita.source,
  external_id  text not null,
  data         jsonb not null,
  hash         bytea not null,
  modified_at  timestamptz,
  loaded_at    timestamptz not null default now(),
  deleted_at   timestamptz,
  unique (source_id, external_id)
);

create table fita.normalized_record (
  source_record_id  uuid primary key references fita.source_record,
  data              jsonb not null,
  blocking_keys     text[] not null default '{}',
  warnings          jsonb not null default '[]',
  normalized_at     timestamptz not null default now()
);

create table fita.master_record (
  id          uuid primary key,
  domain_id   uuid not null references fita.domain,
  public_id   text not null unique,
  created_at  timestamptz not null default now(),
  retired_at  timestamptz
);

-- A source record belongs to one golden record at a time.
create table fita.master_member (
  master_id        uuid not null references fita.master_record,
  source_record_id uuid not null references fita.source_record,
  rule             text,
  confidence       real,
  decided_by       text not null,          -- engine or a decision id
  valid            tstzrange not null,
  exclude using gist (source_record_id with =, valid with &&)
);

-- An attribute of a golden record has one current value at a time.
create table fita.master_value (
  master_id        uuid not null references fita.master_record,
  attribute        text not null,
  value            text not null,
  source_record_id uuid not null references fita.source_record,
  strategy         text not null,
  valid            tstzrange not null,
  exclude using gist (master_id with =, attribute with =, valid with &&)
);

-- Retired public ids point to the golden record that absorbed them.
create table fita.master_redirect (
  from_public_id  text primary key,
  to_master_id    uuid not null references fita.master_record,
  created_at      timestamptz not null default now()
);

create table fita.run (
  id           uuid primary key,
  domain_id    uuid not null references fita.domain,
  started_at   timestamptz not null default now(),
  finished_at  timestamptz,
  status       text not null check (status in ('running', 'succeeded', 'failed')),
  summary      jsonb
);
